function sweptRectHit(ax, ay, bx, by, rect, radius):
  dx = bx - ax
  dy = by - ay
  // expand rect by radius
  minX = rect.x - radius
  maxX = rect.x + rect.w + radius
  minY = rect.y - radius
  maxY = rect.y + rect.h + radius

  // solve t for each axis
  let tmin = 0, tmax = 1
  let nx = 0, ny = 0
  for each axis (x):
    if dx == 0:
      if ax < minX or ax > maxX: return no hit
    else:
      let t1 = (minX - ax)/dx
      let t2 = (maxX - ax)/dx
      if t1 > t2: swap, and flip normal sign
      if t1 > tmin: tmin = t1; nx = sign? 
      if t2 < tmax: tmax = t2
      if tmin > tmax: return no hit
  // similarly y
  ...
  return { t: tmin, nx, ny }
```

