```js
// Returns { t, nx, ny } for the earliest hit of the moving ball (swept from
// (prevX,prevY) to (curX,curY), radius r) against the brick, or null.
function sweptBrickHit(prevX, prevY, curX, curY, brick, r) {
  const dx = curX - prevX;
  const dy = curY - prevY;
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;

  let tmin = 0;
  let tmax = 1;
  let nx = 0;
  let ny = 0;

  if (Math.abs(dx) < 1e-9) {
    if (prevX < minX || prevX > maxX) return null; // never crosses X slab
  } else {
    let t1 = (minX - prevX) / dx;
    let t2 = (maxX - prevX) / dx;
    let normal = -1;
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; normal = 1; }
    if (t1 > tmin) { tmin = t1; nx = normal; }
    if (t2 < tmax) tmax = t2;
    if (tmin > tmax) return null;
  }

  if (Math.abs(dy) < 1e-9) {
    if (prevY < minY || prevY > maxY) return null;
  } else {
    let t1 = (minY - prevY) / dy;
    let t2 = (maxY - prevY) / dy;
    let normal = -1;
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; normal = 1; }
    if (t1 > tmin) { tmin = t1; ny = normal; }
    if (t2 < tmax) tmax = t2;
    if (tmin > tmax) return null;
  }

  if (tmin >= 0 && tmin <= 1) {
    return { t: tmin, nx, ny };
  }
  return null;
}
```

