```js
export function resolveBrickCollision(state, dt) {
  const { ball, bricks } = state;
  const prevX = ball.x - ball.vx * dt;
  const prevY = ball.y - ball.vy * dt;

  // First pass: destroy every brick hit along the path; record the earliest.
  let earliest = null; // { t, nx, ny }
  let firstBrick = null;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweptBrickHit(prevX, prevY, ball.x, ball.y, brick, ball.r);
    if (!hit) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    if (!earliest || hit.t < earliest.t) {
      earliest = hit;
      firstBrick = brick;
    }
  }
  if (!earliest) return;

  // Reposition the ball to the impact point and nudge it out, then flip.
  const hitX = prevX + (ball.x - prevX) * earliest.t;
  const hitY = prevY + (ball.y - prevY) * earliest.t;
  ball.x = hitX;
  ball.y = hitY;

  // Flip along the collision normal; corner (both non-zero) flips both.
  if (earliest.nx !== 0) {
    ball.vx = -ball.vx;
    // push out horizontally
    ball.x += (earliest.nx > 0 ? 1 : -1) * (ball.r + 0.01);
  }
  if (earliest.ny !== 0) {
    ball.vy = -ball.vy;
    ball.y += (earliest.ny > 0 ? 1 : -1) * (ball.r + 0.01);
  }
}
```

