// --- Physics (movement + wall/paddle/brick bounces) -----------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. The brick bounce is handled here too
// (it needs dt and the previous position for the tunnelling-proof sweep).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the ball was before this step: the sweep in the brick
  // resolver needs it to catch fast shots that skip between two frames.
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

